  "v_opp": { topic: "vocab", cards: [
    {"id": "v_opp_94e31a3c", "kind": "type", "q": "What is the opposite? POSSIBLE", "a": ["impossible"], "note": "Before possible we use the prefix im-, which is used before words starting with p. Unpossible is not correct.", "sec": "v_opp"},
    {"id": "v_opp_d067ccb2", "kind": "type", "q": "What is the opposite? VISIBLE", "a": ["invisible"], "note": "The usual opposite of visible is invisible. The prefix un- is not used with this word.", "sec": "v_opp"},
    {"id": "v_opp_2cc47e26", "kind": "type", "q": "What is the opposite? APPROPRIATE", "a": ["inappropriate"], "note": "The opposite is formed with in-: inappropriate. Unappropriate is not correct.", "sec": "v_opp"},
    {"id": "v_opp_349bf7bd", "kind": "type", "q": "What is the opposite? CONVENIENT", "a": ["inconvenient"], "note": "Before convenient we use in-, so the correct form is inconvenient. The prefix un- does not fit here.", "sec": "v_opp"},
    {"id": "v_opp_797366cd", "kind": "type", "q": "What is the opposite? PREDICTABLE", "a": ["unpredictable"], "note": "The opposite is formed with un-: unpredictable. It means that something cannot be foreseen.", "sec": "v_opp"},
    {"id": "v_opp_ce767421", "kind": "type", "q": "What is the opposite? REGULAR", "a": ["irregular"], "note": "Before regular we use ir-, so irregular is correct. Unregular is not correct.", "sec": "v_opp"},
    {"id": "v_opp_a2fae11e", "kind": "type", "q": "What is the opposite? ACCURATE", "a": ["inaccurate"], "note": "The opposite is formed with in-: inaccurate. It means not exact, not wrong in every sense.", "sec": "v_opp"},
    {"id": "v_opp_ed5ffdef", "kind": "type", "q": "What is the opposite? FAIR", "a": ["unfair"], "note": "Before fair we use un-, so the opposite is unfair. In-fair does not exist.", "sec": "v_opp"},
    {"id": "v_opp_719f91a9", "kind": "type", "q": "What is the opposite? FRIENDLY", "a": ["unfriendly"], "note": "The opposite is formed with un-: unfriendly. The prefix dis- is not used with this word.", "sec": "v_opp"},
    {"id": "v_opp_e8db4324", "kind": "type", "q": "What is the opposite? SATISFIED", "a": ["dissatisfied", "unsatisfied"], "note": "Dissatisfied is the usual opposite of satisfied; unsatisfied is also correct. The prefix im- does not fit here.", "sec": "v_opp"},
    {"id": "v_opp_9507f9ee", "kind": "type", "q": "What is the opposite? CONSCIOUS", "a": ["unconscious"], "note": "The opposite of conscious is unconscious. The prefix un- changes the meaning to 'not awake'.", "sec": "v_opp"},
    {"id": "v_opp_bdf78517", "kind": "type", "q": "What is the opposite? DEPENDENT", "a": ["independent"], "note": "The opposite of dependent is independent. This word takes in-, not un-.", "sec": "v_opp"},
    {"id": "v_opp_3af32703", "kind": "type", "q": "What is the opposite? EXPERIENCED", "a": ["inexperienced"], "note": "Before experienced we use in-: inexperienced. It means the person has no experience.", "sec": "v_opp"},
    {"id": "v_opp_b89da04d", "kind": "type", "q": "What is the opposite? EFFICIENT", "a": ["inefficient"], "note": "The opposite of efficient is inefficient. The prefix in- means that something does not work well.", "sec": "v_opp"},
    {"id": "v_opp_091eede0", "kind": "type", "q": "What is the opposite? FORMAL", "a": ["informal"], "note": "The opposite of formal is informal, formed with in-. Unformal is not standard.", "sec": "v_opp"},
    {"id": "v_opp_28105dfc", "kind": "type", "q": "What is the opposite? HONEST", "a": ["dishonest"], "note": "The prefix dis- forms the opposite of the adjective honest.", "sec": "v_opp"},
    {"id": "v_opp_7060b853", "kind": "type", "q": "What is the opposite? PATIENT", "a": ["impatient"], "note": "The prefix im- negates the adjective patient; impatient means not able to wait calmly.", "sec": "v_opp"},
    {"id": "v_opp_4a6f651e", "kind": "type", "q": "What is the opposite? RESPONSIBLE", "a": ["irresponsible"], "note": "The prefix ir- forms the opposite of the adjective responsible.", "sec": "v_opp"},
    {"id": "v_opp_45749db3", "kind": "type", "q": "What is the opposite? TIGHT (clothes)", "a": ["loose"], "note": "For clothes we use loose as the opposite of tight; untight is not a normal word.", "sec": "v_opp"},
    {"id": "v_opp_8e461642", "kind": "type", "q": "What is the opposite? MATURE", "a": ["immature"], "note": "The prefix im- forms the opposite of the adjective mature.", "sec": "v_opp"},
    {"id": "v_opp_59197b8d", "kind": "type", "q": "What is the opposite? CONSIDERATE", "a": ["inconsiderate"], "note": "The prefix in- forms the opposite of the adjective considerate.", "sec": "v_opp"},
    {"id": "v_opp_369b7316", "kind": "type", "q": "What is the opposite? RELIABLE", "a": ["unreliable"], "note": "The prefix un- forms the opposite of the adjective reliable.", "sec": "v_opp"},
    {"id": "v_opp_36241e6d", "kind": "type", "q": "What is the opposite? SECURE", "a": ["insecure"], "note": "The prefix in- forms the opposite of the adjective secure.", "sec": "v_opp"},
    {"id": "v_opp_120e4b7b", "kind": "type", "q": "What is the opposite? TIDY", "a": ["untidy"], "note": "The prefix un- forms the opposite of the adjective tidy.", "sec": "v_opp"},
    {"id": "v_opp_12c7ea75", "kind": "type", "q": "What is the opposite? OBEDIENT", "a": ["disobedient"], "note": "The prefix dis- forms the opposite of the adjective obedient.", "sec": "v_opp"},
    {"id": "v_opp_9ab83b0f", "kind": "type", "q": "What is the opposite? RATIONAL", "a": ["irrational"], "note": "The prefix ir- forms the opposite of the adjective rational.", "sec": "v_opp"},
    {"id": "v_opp_f06318b1", "kind": "type", "q": "What is the opposite? TOLERANT", "a": ["intolerant"], "note": "The prefix in- forms the opposite of the adjective tolerant.", "sec": "v_opp"},
    {"id": "v_opp_70df3f88", "kind": "type", "q": "What is the opposite? HELPFUL", "a": ["unhelpful"], "note": "The prefix un- forms the opposite of the adjective helpful.", "sec": "v_opp"},
    {"id": "v_opp_15813e15", "kind": "type", "q": "What is the opposite? LEGAL", "a": ["illegal"], "note": "The prefix il- forms the opposite of the adjective legal.", "sec": "v_opp"},
    {"id": "v_opp_b96e5df3", "kind": "type", "q": "What is the opposite? LOYAL", "a": ["disloyal"], "note": "The prefix dis- forms the opposite of the adjective loyal.", "sec": "v_opp"},
  ] },
